160	import org.springframework.dao.DataIntegrityViolationException;
161	import org.springframework.http.HttpStatus;
162	import org.springframework.stereotype.Service;
163	import org.springframework.transaction.annotation.Transactional;
164	import org.springframework.web.server.ResponseStatusException;
165	
166	@Service
167	public class PeriodService {
168	
169	    private final PeriodRepository periods;
170	    private final SheetService sheets;
171	    private final RollupService rollup;
172	    private final Audit audit;
173	
174	    public PeriodService(PeriodRepository periods, SheetService sheets, RollupService rollup, Audit audit) {
175	        this.periods = periods;
176	        this.sheets = sheets;
177	        this.rollup = rollup;
178	        this.audit = audit;
179	    }
180	
181	    /** The sheet's periods by from-date. */
182	    @Transactional(readOnly = true)
183	    public List<Period> list(String sheetId) {
184	        sheets.today(sheetId); // the sheet must exist
185	        return periods.findBySheetIdOrderByFromAsc(sheetId);
186	    }
187	
188	    /** Add a period; one whose to-date is before its from-date, whose name is taken on the sheet, or that
189	     * overlaps another of the sheet's periods is refused. */
190	    @Transactional
191	    public Period add(String user, String sheetId, String name, LocalDate from, LocalDate to) {
192	        // Locking the sheet adds its periods one at a time, so two at once cannot overlap.
193	        sheets.lock(sheetId);
194	        String trimmed = name.trim();
195	        if (to.isBefore(from)) {
196	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts.");
197	        }
198	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
199	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
200	        }
201	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
202	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
203	        }
204	        Period period;
205	        try {
206	            period = periods.saveAndFlush(new Period(sheetId, trimmed, from, to));
207	        } catch (DataIntegrityViolationException e) {
208	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
209	        }
210	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
211	                + " from=" + period.getFrom() + " to=" + period.getTo());
212	        return period;
213	    }
214	
215	    /** Close a period, fixing its due-total as it is now; closing one already closed is refused. */
216	    @Transactional
217	    public Period close(String user, String sheetId, Long id) {
218	        // Locking the sheet keeps claims from changing while the total is taken.
219	        sheets.lock(sheetId);
220	        Period period = periods.findByIdAndSheetId(id, sheetId)
221	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
222	        if (period.isClosed()) {
223	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
224	        }
225	        BigDecimal total = rollup.dueTotal(sheetId, period.getFrom(), period.getTo());
226	        period.close(total);
227	        periods.flush();
228	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
229	                + " total=" + total.toPlainString());
230	        return period;
231	    }
232	
233	    /** Refuse a change to a claim dated in one of the sheet's closed periods. */
234	    @Transactional(readOnly = true)
235	    public void requireOpen(String sheetId, LocalDate date) {
236	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.isClosed() && p.contains(date))) {
237	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim is dated in a closed period.");
238	        }
239	    }
