443	    /** The role a user name has on the sheet: a clerk unless given another. */
444	    @Transactional(readOnly = true)
445	    public Role roleOf(String sheetId, String user) {
446	        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
447	    }
