449	    /** Give a user name a role on the sheet, replacing any it had. */
450	    @Transactional
451	    public SheetRole setRole(String user, String sheetId, String name, Role role) {
452	        sheets.lock(sheetId);
453	        SheetRole given = roles.findBySheetIdAndUser(sheetId, name).orElse(null);
454	        if (given == null) {
455	            given = roles.saveAndFlush(new SheetRole(sheetId, name, role));
456	        } else {
457	            given.setRole(role);
458	            roles.flush();
459	        }
460	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.code());
461	        return given;
462	    }
