464	    /** Save the settings given, the clerk limit then the floor, together; a setting not given (null) is left as
465	     * it is, and an empty clerk limit removes it. */
466	    @Transactional
467	    public void save(String user, String sheetId, Optional<BigDecimal> clerkLimit, BigDecimal floor) {
468	        if (clerkLimit != null) {
469	            setClerkLimit(user, sheetId, clerkLimit.orElse(null));
470	        }
471	        if (floor != null) {
