551	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
552	 * so tests can assert side-effects by reading that file — the second test-assertion channel
553	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
554	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
555	 *
556	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
557	 * SYNC) so a test reads the record immediately.
558	 */
559	@Service
560	public class Audit {
561	
562	    private final Path file;
563	
564	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
565	        this.file = Path.of(path);
566	    }
567	
568	    /** Append one audit record. Tests assert the exact line(s) in the file. */
569	    public synchronized void record(String entry) {
570	        try {
571	            Path parent = file.toAbsolutePath().getParent();
572	            if (parent != null) {
573	                Files.createDirectories(parent);
574	            }
575	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
576	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
577	        } catch (IOException e) {
578	            throw new UncheckedIOException(e);
579	        }
580	    }
581	
582	    /**
583	     * Append one audit record once the current transaction commits, so a change that is refused or
584	     * rolled back writes nothing. Outside a transaction the record is appended at once.
585	     */
586	    public void recordOnCommit(String entry) {
587	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
588	            record(entry);
589	            return;
590	        }
591	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
592	            @Override
593	            public void afterCommit() {
594	                record(entry);
595	            }
596	        });
597	    }
598	
599	    /** Truncate the audit file. */
600	    public synchronized void clear() {
601	        try {
602	            Files.deleteIfExists(file);
603	        } catch (IOException e) {
604	            throw new UncheckedIOException(e);
605	        }
606	    }
