648	    public StatementService(StatementRepository statements, ClaimRepository claims, ClaimService claimService,
649	            PersonRepository people, RateRepository rates, SheetService sheets, RollupService rollup, Audit audit) {
650	        this.statements = statements;
651	        this.claims = claims;
652	        this.claimService = claimService;
653	        this.people = people;
654	        this.rates = rates;
655	        this.sheets = sheets;
656	        this.rollup = rollup;
657	        this.audit = audit;
658	    }
