660	    /** Each person's statements on the sheet, by person id. */
661	    @Transactional(readOnly = true)
662	    public Map<Long, Summary> summaries(String sheetId) {
663	        Map<Long, Summary> by = new HashMap<>();
664	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
665	            Summary was = by.get(s.getPersonId());
666	            by.put(s.getPersonId(), new Summary(was == null ? 1 : was.count() + 1, s));
667	        }
668	        return by;
669	    }
