671	    /**
672	     * Take a statement for a person: record their due-total now and bind each of their claims that counts to
673	     * the figure it has now; a claim of theirs that does not count is left unbound.
674	     */
675	    @Transactional
676	    public Person take(String user, String sheetId, Long personId) {
677	        LocalDate today = sheets.today(sheetId);
678	        Person person = people.findByIdAndSheetId(personId, sheetId)
679	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
680	        String grade = person.getGrade();
681	        Snapshot before = rollup.snapshot(sheetId);
682	        BigDecimal total = BigDecimal.ZERO.setScale(2);
683	        boolean fixed = false;
684	        int counted = 0;
685	        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
686	            if (!counts(claim)) {
687	                claim.unbind();
688	                continue;
689	            }
690	            BigDecimal figure = claimService.figureOf(claim, grade);
691	            fixed |= RollupService.keepsFigure(claim);
692	            claim.bind(figure);
693	            counted++;
694	            if (figure != null) {
695	                total = total.add(figure);
696	            }
697	        }
698	        // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
699	        boolean rated = Rate.inForce(rates.findBySheetIdAndGrade(sheetId, grade), today).isPresent();
700	        BigDecimal dueTotal = rated || fixed ? total : null;
701	        claims.flush();
702	        statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted));
703	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
704	                + " due-total=" + (dueTotal != null ? dueTotal.toPlainString() : "n/a")
705	                + " claims=" + counted);
706	        rollup.recordChanges(user, sheetId, before);
707	        return person;
708	    }
709	
710	    /** Only OPEN and SETTLED claims count toward what is claimed and due. */
711	    private static boolean counts(Claim claim) {
712	        return claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
713	    }
