1314	    /** The sheet's figures now; none (an empty sheet's) when there is no such sheet. */
1315	    public Snapshot snapshot(String sheetId) {
1316	        LocalDate today = sheets.findById(sheetId).map(s -> s.getToday()).orElse(null);
1317	        BigDecimal floor = floorOf(sheetId);
1318	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
1319	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1320	            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
1321	        }
1322	        Map<Long, Figures> figures = new LinkedHashMap<>();
1323	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
1324	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
1325	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
1326	            List<Rate> gradeRates = rates.findBySheetIdAndGrade(sheetId, person.getGrade());
1327	            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
1328	                    .filter(c -> counts(c, person)).toList();
1329	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
1330	            BigDecimal due = BigDecimal.ZERO.setScale(2);
1331	            boolean frozen = false;
1332	            for (Claim claim : counted) {
1333	                claimed = claimed.add(claim.getAmount().setScale(2));
1334	                frozen |= keepsFigure(claim);
