1341	            boolean rated = today != null && Rate.inForce(gradeRates, today).isPresent();
1342	            String personDue = rated || frozen ? due.toPlainString() : NO_RATE;
1343	            claimedTotal = claimedTotal.add(claimed);
1344	            if (rated || frozen) {
1345	                dueTotal = dueTotal.add(due);
1346	            }
1347	            figures.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), personDue));
