1354	    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
1355	        BigDecimal floor = floorOf(sheetId);
1356	        Map<Long, List<Rate>> gradeRates = new LinkedHashMap<>();
1357	        Map<Long, Person> byId = new LinkedHashMap<>();
1358	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
1359	            gradeRates.put(person.getId(), rates.findBySheetIdAndGrade(sheetId, person.getGrade()));
1360	            byId.put(person.getId(), person);
1361	        }
1362	        BigDecimal total = BigDecimal.ZERO.setScale(2);
1363	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1364	            List<Rate> personRates = gradeRates.get(claim.getPersonId());
1365	            if (personRates == null || !counts(claim, byId.get(claim.getPersonId()))
1366	                    || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
1367	                continue;
1368	            }
1369	            BigDecimal figure = figureOf(claim, personRates, floor);
1370	            if (figure != null) {
1371	                total = total.add(figure.setScale(2));
1372	            }
1373	        }
1374	        return total;
