1379	     * {@code before} (a person new since then counts as moved), in the order they were added, then a TOTALS
1380	     * line when the sheet's totals moved.
1381	     */
1382	    public void recordChanges(String user, String sheetId, Snapshot before) {
1383	        claims.flush();
1384	        Snapshot after = snapshot(sheetId);
1385	        String prefix = " sheet=" + sheetId + " by=" + user;
1386	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
1387	            Figures now = e.getValue();
1388	            Figures was = before.people().get(e.getKey());
1389	            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())) {
1390	                continue;
1391	            }
1392	            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
1393	                    + " due-total=" + now.dueTotal());
1394	        }
1395	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
1396	                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
1397	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
1398	                    + " due-total=" + after.dueTotal());
1399	        }
1400	    }
