1416	     * decimals, and at least the floor; none when no rate of the grade applies then. */
1417	    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, BigDecimal floor) {
1418	        BigDecimal amount = claim.getAmount();
1419	        return Rate.inForce(gradeRates, claim.getDate())
1420	                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
1421	                .map(due -> due.max(floor.setScale(2)))
1422	                .orElse(null);
1423	    }
